select jsonb_build_object(
    'operational', coalesce((
      select jsonb_agg(v order by v) from (
        select distinct operational_status as v
        from order_master where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and operational_status is not null
      ) q
    ), '[]'::jsonb),
    'courier', coalesce((
      select jsonb_agg(v order by v) from (
        select current_courier as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and current_courier is not null
        union
        select last_courier as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and last_courier is not null
      ) q
    ), '[]'::jsonb),
    'region', coalesce((
      select jsonb_agg(v order by v) from (
        select distinct region as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and region is not null
      ) q
    ), '[]'::jsonb),
    'province', coalesce((
      select jsonb_agg(v order by v) from (
        select distinct province as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and province is not null
      ) q
    ), '[]'::jsonb),
    'district', coalesce((
      select jsonb_agg(v order by v) from (
        select distinct district as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and district is not null
      ) q
    ), '[]'::jsonb),
    'coverage', coalesce((
      select jsonb_agg(v order by v) from (
        select distinct coverage as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and coverage is not null
      ) q
    ), '[]'::jsonb),
    'pickup', coalesce((
      select jsonb_agg(v order by v) from (
        select distinct pickup_state as v from order_master
        where store_id = any(array['01570000-0000-4000-8000-000000000011'::uuid,'01570000-0000-4000-8000-000000000012'::uuid]) and pickup_state is not null
      ) q
    ), '[]'::jsonb)
  )

